-- Ejecutar en Supabase -> SQL Editor -> New query -> Run.
-- Parte 4 de 7. Requiere 01_esquema.sql (columnas profile, skills y
-- mindscapes de characters) y 04_personajes_zzz.sql.
--
-- Datos de los agentes de Zenless Zone Zero sacados de HoYoWiki, la wiki oficial de
-- HoYoverse, con los textos oficiales en espanol:
--   profile     -> sexo, afiliacion, estatura, cumpleanos, actores de voz y version.
--   skills      -> las seis categorias de tecnicas (ataque normal, evasion,
--                  tecnica de apoyo, tecnica especial, tecnica en cadena y
--                  habilidad fundamental) con sus valores por nivel y los
--                  materiales para subirlas.
--   mindscapes  -> los seis niveles de Cine mental.
-- Ademas, los agentes que no tenian biografia reciben el "Diseño de personaje"
-- de la wiki (los que ya tenian una se dejan como estan).
--
-- Sin ficha en la wiki todavia: zzz-roxy.
--
-- Solo actualiza agentes que ya existen; no crea ninguno. Se puede repetir.
--
-- Generado el 2026-09-15.

update public.characters as c
set profile = v.profile,
    skills = v.skills,
    mindscapes = v.mindscapes,
    biography_es = coalesce(c.biography_es, v.biography),
    biography_source_es = case when c.biography_es is null and v.biography is not null then v.source else c.biography_source_es end
from (
  values
  ('zzz-alice', '[{"campo":"Versión de lanzamiento","valor":"2.1"},{"campo":"Sexo","valor":"Femenino"},{"campo":"Afiliación","valor":"Cabaña del Terror"},{"campo":"Estatura","valor":"163 cm (incluyendo las orejas)"},{"campo":"Cumpleaños","valor":"30 de agosto"},{"campo":"Amplificador exclusivo","valor":"Excelencia disciplinada"},{"campo":"Afiliación común","valor":"Ukinami Yuzuha, Señorita Esme, Komano Manato, Lucía, Yidhari"},{"campo":"VA (CN)","valor":"Duoduo Poi (多多POI)"},{"campo":"VA (JP)","valor":"Minami Tanaka (田中美海)"},{"campo":"VA (KO)","valor":"Park Shi-yoon (박시윤)"},{"campo":"VA (EN)","valor":"Diana Garnet"}]'::jsonb, '{"categorias":[{"categoria":"Ataque normal","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/08/26/7c4749265d45177f16044c76d9315db0_7689331585667217268.png","tecnicas":[{"nombre":"Ataque normal: Obertura celeste","descripcion":"Pulsa para usarla.\nEjecuta hasta cinco cortes hacia delante, lo que inflige daño físico. Cuando Alice provoca una embestida mediante la acumulación de Anomalía de Atributo, refuerza el quinto corte del siguiente ataque normal."},{"nombre":"Ataque normal: Vals de la refulgencia astrífera","descripcion":"Cuando Alice tiene 1 barra de etiqueta de espada, mantén pulsado para usarla.\nMantén pulsado para acumular fuerza y consumir hasta 3 barras de etiqueta de espada. Al soltar o cuando etiqueta de espada cuente con menos de 1 barra, Alice ejecuta múltiples cortes en un área cuyo centro es el enemigo objetivo en función del nivel de fuerza acumulada, lo que inflige una gran cantidad de daño físico. Al golpear a un enemigo con el ataque final con tres niveles de carga del ataque normal: Vals de la refulgencia astrífera, activa una instancia especial de embestida llamada embestida polarizada, que ignora la acumulación de Anomalía de Atributo e inflige un 100% del daño original del efecto de embestida. Este efecto puede interactuar otras Anomalías de Atributo, lo que incluye la Anomalía física, y a