e daño físico.\nDurante su ejecución, el agente se vuelve invulnerable."}],"atributos":[{"clave":"Apoyo rápido: Fortuna a primera vista","valores":["Nivel 1","Nivel 2","Nivel 3","Nivel 4","Nivel 5","Nivel 6","Nivel 7","Nivel 8","Nivel 9","Nivel 10","Nivel 11","Nivel 12","Nivel 13","Nivel 14","Nivel 15","Nivel 16"]},{"clave":"Multiplicador de daño","valores":["91.7%","100.1%","108.5%","116.9%","125.3%","133.7%","142.1%","150.5%","158.9%","167.3%","175.7%","184.1%","192.5%","200.9%","209.3%","217.7%"]},{"clave":"Multiplicador de Aturdimiento","valores":["45.9%","48%","50.1%","52.2%","54.3%","56.4%","58.5%","60.6%","62.7%","64.8%","66.9%","69.0%","71.1%","73.2%","75.3%","77.4%"]},{"clave":"","valores":["","","","","","","","","","","","","","","",""]},{"clave":"Apoyo defensivo: Presencia intimidadora","valores":["Nivel 1","Nivel 2","Nivel 3","Nivel 4","Nivel 5","Nivel 6","Nivel 7","Nivel 8","Nivel 9","Nivel 10","Nivel 11","Nivel 12","Nivel 13","Nivel 14","Nivel 15","Nivel 16"]},{"clave":"Multiplicador de Aturdimiento ligero","valores":["225.1%","235.4%","245.7%","256%","266.3%","276.6%","286.9%","297.2%","307.5%","317.8%","328.1%","338.4%","348.7%","359%","369.3%","379.6%"]},{"clave":"Multiplicador de Aturdimiento fuerte","valores":["268.4%","280.6%","292.8%","305%","317.2%","329.4%","341.6%","353.8%","366%","378.2%","390.4%","402.6%","414.8%","427%","439.2%","451.4%"]},{"clave":"Multiplicador de Aturdimiento continuo","valores":["108.4%","113.4%","118.4%","123.4%","128.4%","133.4%","138.4%","143.4%","148.4%","153.4%","158.4%","163.4%","168.4%","173.4%","178.4%","183.4%"]},{"clave":"","valores":["","","","","","","","","","","","","","","",""]},{"clave":"Ataque sucesivo: Impulso oportuno","valores":["Nivel 1","Nivel 2","Nivel 3","Nivel 4","Nivel 5","Nivel 6","Nivel 7","Nivel 8","Nivel 9","Nivel 10","Nivel 11","Nivel 12","Nivel 13","Nivel 14","Nivel 15","Nivel 16"]},{"clave":"Multiplicador de daño","valores":["337.4%","368.1%","398.8%","429.5%","460.2%","490.9%","521.6%